function stablePhotoIndex(key: string, length: number): number {
  if (length <= 1) {
    return 0;
  }

  let hash = 0;
  for (let index = 0; index < key.length; index += 1) {
    hash = (hash * 31 + key.charCodeAt(index)) % length;
  }
  return hash;
}

export function getRoutePreviewPhoto(route: RoutePhotoTarget): RoutePreviewPhoto {
  const marylandContextPhoto = route.state === 'Maryland' && route.riverId
    ? approvedMarylandContextPhotosByRiverId[route.riverId]
    : undefined;
  if (marylandContextPhoto) {
    return {
      ...marylandContextPhoto,
      id: `maryland-context-${route.riverId}-${marylandContextPhoto.id}`,
      isPlaceholder: false,
      sourceKind: 'river',
    };
  }

  const approvedPhotos = getApprovedRoutePhotos(route.slug);
  const key = `${route.riverId ?? 'route'}:${route.slug}`;

  if (approvedPhotos.length > 0) {
    const photo = approvedPhotos[stablePhotoIndex(key, approvedPhotos.length)];
    return {
      ...photo,
      isPlaceholder: false,
      sourceKind: 'route',
    };
  }

  const riverPhoto = getDedicatedRiverGroupHeroPhoto(route.riverId);
  if (riverPhoto) {
    return {
      id: `river-group-${route.riverId}`,
      src: riverPhoto.src,
      alt: riverPhoto.alt,
      caption: `${riverPhoto.caption} river-level photo`,
      credit: riverPhoto.credit,
      takenLabel: riverPhoto.licenseLabel,
      isPlaceholder: false,
      sourceKind: 'river',
    };
  }

  const riverContextPhoto = route.riverId
    ? approvedRiverContextPhotosByRiverId[route.riverId]
    : undefined;
  if (riverContextPhoto) {
    return {
      ...riverContextPhoto,
      id: `river-context-${route.riverId}-${riverContextPhoto.id}`,
      caption: `${riverContextPhoto.caption} river-level context`,
      isPlaceholder: false,
      sourceKind: 'river',
    };
  }

  const fallbackRouteSlug = route.riverId
    ? approvedRiverFallbackRouteById[route.riverId]
    : undefined;
  const sameRiverPhoto = fallbackRouteSlug
    ? getApprovedRoutePhotos(fallbackRouteSlug)[0]
    : undefined;
  if (sameRiverPhoto) {
    return {
      ...sameRiverPhoto,
      id: `river-route-${route.riverId}-${sameRiverPhoto.id}`,
      caption: `${sameRiverPhoto.caption} river-level photo`,
      isPlaceholder: false,
      sourceKind: 'river',
    };
  }

  const regionalContextPhoto = route.riverId
    ? approvedRegionalContextPhotosByRiverId[route.riverId]
    : undefined;
  if (regionalContextPhoto) {
    return {
      ...regionalContextPhoto,
      id: `regional-context-${route.riverId}-${regionalContextPhoto.id}`,
      isPlaceholder: false,
      sourceKind: 'river',
    };
  }

  const fallback = placeholderRoutePhotos[stablePhotoIndex(key, placeholderRoutePhotos.length)];
  const routeLabel = [route.name, route.reach].filter(Boolean).join(' - ');
  return {
    ...fallback,
    alt: routeLabel
      ? `Placeholder river image for ${routeLabel}.`
      : fallback.alt,
    isPlaceholder: true,
    sourceKind: 'placeholder',
  };
}
